#[inline]
pub unsafe fn root_as_pvn_unchecked(buf: &[u8]) -> PVN<'_> {
    unsafe { ::flatbuffers::root_unchecked::<PVN>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed PVN and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `PVN`.
#[inline]
pub unsafe fn size_prefixed_root_as_pvn_unchecked(buf: &[u8]) -> PVN<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<PVN>(buf) }
}

pub const PVN_IDENTIFIER: &str = "$PVN";

#[inline]
pub fn pvn_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, PVN_IDENTIFIER, false)
}

#[inline]
pub fn pvn_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, PVN_IDENTIFIER, true)
}

#[inline]
pub fn finish_pvn_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<PVN<'a>>
) {
    fbb.finish(root, Some(PVN_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_pvn_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<PVN<'a>>
) {
    fbb.finish_size_prefixed(root, Some(PVN_IDENTIFIER));
}
